fn solve(t: Vec<char>) -> Vec<char> {
    // Input is assumed non-empty, but the logic works for empty as well.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // Measure for termination (conceptually): n - i, strictly decreases each iteration.
    let mut i: usize = 0;
    while i < n {
        // Maintain prefix property: out[k] == t[k] for all k < out.len().
        out.push(t[i]);
        i += 1;
    }

    debug_assert_eq!(out.len(), n);
    out
}